-- ADMINISTRATOR TEMPLATE ONLY. NOT EXECUTED BY THIS TASK. NO BUSINESS/AUTH ROWS.
-- Catalog deparsing may reveal literals in definitions: administrator reviews/redacts
-- secrets BEFORE sharing, preserves provenance/hash of restricted original separately.
-- A single read-only repeatable-read transaction, no DDL, grants, role/password changes,
-- user/session reads, sequence values, row estimates or general application SELECTs.
begin transaction isolation level repeatable read read only;
select jsonb_build_object(
 'captured_at',transaction_timestamp(),
 'database',current_database(),
 'executor',current_user,
 'postgres_version',version(),
 'scope','Catalog metadata only. NOT a complete original schema restore.',
 'schemas',(select coalesce(jsonb_agg(jsonb_build_object('schema',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text) order by nspname),'[]') from pg_namespace where nspname not like 'pg_%' and nspname<>'information_schema'),
 'relations',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'persistence',c.relpersistence,'options',c.reloptions,'partition_bound',pg_get_expr(c.relpartbound,c.oid)) order by n.nspname,c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname not like 'pg_%' and n.nspname<>'information_schema' and c.relkind in('r','p','v','m','S','f')),
 'columns',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',a.attname,'ordinal',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'acl',a.attacl::text,'default',pg_get_expr(d.adbin,d.adrelid)) order by n.nspname,c.relname,a.attnum),'[]') from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where n.nspname not like 'pg_%' and n.nspname<>'information_schema' and c.relkind in('r','p','v','m','f') and a.attnum>0 and not a.attisdropped),
 'constraints',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',k.conname,'type',k.contype,'validated',k.convalidated,'deferrable',k.condeferrable,'deferred',k.condeferred,'definition',pg_get_constraintdef(k.oid),'referenced_relation',k.confrelid::regclass::text) order by n.nspname,c.relname,k.conname),'[]') from pg_constraint k left join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=k.connamespace where n.nspname not like 'pg_%' and n.nspname<>'information_schema'),
 'policies',(select coalesce(jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'policy',policyname,'permissive',permissive,'roles',roles,'command',cmd,'using',qual,'with_check',with_check) order by schemaname,tablename,policyname),'[]') from pg_policies where schemaname not like 'pg_%'),
 'functions',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity_arguments',pg_get_function_identity_arguments(p.oid),'arguments',pg_get_function_arguments(p.oid),'result',pg_get_function_result(p.oid),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl::text,'volatility',p.provolatile,'definition',pg_get_functiondef(p.oid)) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname not like 'pg_%' and n.nspname<>'information_schema' and p.prokind in('f','p')),
 'views',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'definition',pg_get_viewdef(c.oid,false),'options',c.reloptions,'populated',c.relispopulated) order by n.nspname,c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname not like 'pg_%' and c.relkind in('v','m')),
 'triggers',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'internal',t.tgisinternal,'function',t.tgfoid::regprocedure::text,'definition',pg_get_triggerdef(t.oid,false)) order by n.nspname,c.relname,t.tgname),'[]') from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname not like 'pg_%'),
 'indexes',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',i.indexrelid::regclass::text,'valid',i.indisvalid,'ready',i.indisready,'unique',i.indisunique,'definition',pg_get_indexdef(i.indexrelid)) order by n.nspname,c.relname,i.indexrelid::regclass::text),'[]') from pg_index i join pg_class c on c.oid=i.indrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname not like 'pg_%'),
 'sequences',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'type',s.seqtypid::regtype::text,'start',s.seqstart,'increment',s.seqincrement,'minimum',s.seqmin,'maximum',s.seqmax,'cache',s.seqcache,'cycle',s.seqcycle) order by n.nspname,c.relname),'[]') from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname not like 'pg_%'),
 'default_acl',(select coalesce(jsonb_agg(jsonb_build_object('creator',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'object_type',d.defaclobjtype,'acl',d.defaclacl::text) order by d.defaclrole,d.defaclnamespace,d.defaclobjtype),'[]') from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace),
 'roles',(select coalesce(jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'inherit',rolinherit,'create_role',rolcreaterole,'create_db',rolcreatedb,'login',rolcanlogin,'replication',rolreplication,'bypass_rls',rolbypassrls) order by rolname),'[]') from pg_roles),
 'memberships',(select coalesce(jsonb_agg(jsonb_build_object('role',pg_get_userbyid(roleid),'member',pg_get_userbyid(member),'grantor',pg_get_userbyid(grantor),'admin',admin_option,'inherit',inherit_option,'set',set_option) order by roleid,member,grantor),'[]') from pg_auth_members),
 'effective_table_rights',(select coalesce(jsonb_agg(jsonb_build_object('table',c.oid::regclass::text,'role',r.rolname,'select',has_table_privilege(r.oid,c.oid,'SELECT'),'insert',has_table_privilege(r.oid,c.oid,'INSERT'),'update',has_table_privilege(r.oid,c.oid,'UPDATE'),'delete',has_table_privilege(r.oid,c.oid,'DELETE'),'truncate',has_table_privilege(r.oid,c.oid,'TRUNCATE'),'references',has_table_privilege(r.oid,c.oid,'REFERENCES'),'trigger',has_table_privilege(r.oid,c.oid,'TRIGGER')) order by c.relname,r.rolname),'[]') from pg_class c cross join pg_roles r join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in('r','p') and r.rolname in('anon','authenticated')),
 'effective_column_rights',(select coalesce(jsonb_agg(jsonb_build_object('table',c.oid::regclass::text,'column',a.attname,'role',r.rolname,'select',has_column_privilege(r.oid,c.oid,a.attnum,'SELECT'),'insert',has_column_privilege(r.oid,c.oid,a.attnum,'INSERT'),'update',has_column_privilege(r.oid,c.oid,a.attnum,'UPDATE'),'references',has_column_privilege(r.oid,c.oid,a.attnum,'REFERENCES')) order by c.relname,a.attnum,r.rolname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid cross join pg_roles r where n.nspname='public' and c.relkind in('r','p') and a.attnum>0 and not a.attisdropped and r.rolname in('anon','authenticated')),
 'extensions',(select coalesce(jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname,'owner',pg_get_userbyid(e.extowner)) order by e.extname),'[]') from pg_extension e join pg_namespace n on n.oid=e.extnamespace),
 'dependencies',(select coalesce(jsonb_agg(jsonb_build_object('object',pg_describe_object(d.classid,d.objid,d.objsubid),'referenced',pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid),'type',d.deptype) order by d.classid,d.objid,d.objsubid,d.refclassid,d.refobjid,d.refobjsubid),'[]') from pg_depend d where (d.classid='pg_class'::regclass and d.objid in(select c.oid from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','humbel_security'))) or (d.classid='pg_proc'::regclass and d.objid in(select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','humbel_security'))) or (d.refclassid='pg_class'::regclass and d.refobjid in(select c.oid from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','humbel_security'))) or (d.refclassid='pg_proc'::regclass and d.refobjid in(select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','humbel_security'))))
) as metadata_only;
commit;
-- Deliver alongside reviewed schema-only pg_dump + role/ACL export and provenance
-- manifest per Step5 runbook. This query is not an auth/API settings export, a full
-- type/domain/extension/event-trigger/foreign-server dump, a data backup or pg_dump.
